recorded_min = df['recorded_at'].min().strftime('%Y-%m-%d')
recorded_max = df['recorded_at'].max().strftime('%Y-%m-%d')
source_min = df['source_updated_at'].min().strftime('%Y-%m-%d')
source_max = df['source_updated_at'].max().strftime('%Y-%m-%d')
clear_errors = df['is_clear_error'].sum()

# Price stats by fuel type (cleaned)
price_stats_clean = {}
for ft in fuel_types:
    subset = df_clean[df_clean['fuel_type'] == ft]['price_pence']
    if len(subset) > 0:
        price_stats_clean[ft] = {
            'count': len(subset),
            'mean': subset.mean(),
            'median': subset.median(),
            'std': subset.std(),
            'min': subset.min(),
            'max': subset.max(),
            'q1': subset.quantile(0.25),
            'q3': subset.quantile(0.75),
            'iqr': subset.quantile(0.75) - subset.quantile(0.25),
            'range': subset.max() - subset.min()
        }

# Price stats by fuel type (full)
price_stats_full = {}
for ft in fuel_types:
    subset = df[df['fuel_type'] == ft]['price_pence']
    price_stats_full[ft] = {
        'count': len(subset),
        'mean': subset.mean(),
        'median': subset.median(),
        'std': subset.std(),
        'min': subset.min(),
        'max': subset.max()
    }

# Update lag stats
lag_stats = {}
for ft in fuel_types:
    subset = df[df['fuel_type'] == ft]['update_lag_hours']
    lag_stats[ft] = {
        'median': subset.median(),
        'mean': subset.mean(),
        'max': subset.max()
    }
overall_median_lag = df['update_lag_hours'].median()
overall_mean_lag = df['update_lag_hours'].mean()
neg_lag_count = (df['update_lag_hours'] < 0).sum()
neg_lag_pct = neg_lag_count / len(df) * 100
stale_24h = (df['update_lag_hours'] > 24).sum()
stale_24h_pct = stale_24h / len(df) * 100
stale_1w = (df['update_lag_hours'] > 168).sum()
stale_1w_pct = stale_1w / len(df) * 100

station_all_stale = df.groupby('node_id').apply(lambda x: (x['update_lag_hours'] > 24).all(), include_groups=False).sum()
station_median_stale = df.groupby('node_id')['update_lag_hours'].median()
station_median_stale_count = (station_median_stale > 24).sum()
station_median_stale_week = (station_median_stale > 168).sum()

# Station coverage
coverage = df.groupby('node_id')['fuel_type'].nunique().value_counts().sort_index()
station_fuel = df.groupby('fuel_type')['node_id'].nunique().sort_values(ascending=False)
records_per_station = df.groupby('node_id').size()

# Weekly trend data
df_trend = df[(df['price_pence'] > 1) & (df['price_pence'] <= 300)].copy()
df_trend['week'] = df_trend['recorded_at'].dt.strftime('%Y-%W')
trend_data = {}
for ft in ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM']:
    subset = df_trend[df_trend['fuel_type'] == ft]
    weekly = subset.groupby('week')['price_pence'].mean().sort_index()
    trend_data[ft] = {w: round(v, 2) for w, v in weekly.items()}

# Monthly price averages
monthly_prices = {}
for ft in ['E10', 'B7_STANDARD', 'E5', 'B7_PREMIUM']:
    subset = df[df['fuel_type'] == ft].copy()
    subset['month'] = subset['recorded_at'].dt.strftime('%Y-%m')
    monthly = subset.groupby('month')['price_pence'].mean()
    monthly_prices[ft] = {m: round(v, 2) for m, v in monthly.items()}

# Error rates
error_rates = {}
